  public function executeExcel()
  {
  	$c = new Criteria();
  	$parametros = '';  	
  	$tipo_documentacion  = $this->getRequestParameter('tipo_documentacion_id');
  	//fiLtros Para los medios Magneticos.
		  $c->addJoin(DocumentacionPeer::DOCUMENTACION_ID,MediosMagneticosPeer::DOCUMENTACION_ID);
		  /*****************************************************************************************************/
    	  if($this->getRequestParameter('formato_id')){
      		$c->add(MediosMagneticosPeer::FORMATO_ID,$this->getRequestParameter('formato_id'));
	  		$parametros .= "&formato_id=".$this->getRequestParameter('formato_id');		
		  }
    	  /*****************************************************************************************************/
		  if($this->getRequestParameter('material_complementario')){
		  	$material =$this->getRequestParameter('material_complementario');
      		$c->add(MediosMagneticosPeer::MATERIAL_COMPLEMENTARIO,'%'.$material.'%',Criteria::LIKE);
	  		$parametros .= "&material_complementario=".$material;		
		  }
         /******************************************************************************************************/
		 if($this->getRequestParameter('notas_contenido')){
		 	$mencion = $this->getRequestParameter('notas_contenido');
      		$c->add(MediosMagneticosPeer::NOTAS_CONTENIDO,'%'.$mencion.'%',Criteria::LIKE);
	  		$parametros .= "&notas_contenido=".$mencion;		
		  }
    	 /*******************************************************************************************************/
		 if($this->getRequestParameter('volumen')){
		  	$volumen = $this->getRequestParameter('volumen');
      		$c->add(MediosMagneticosPeer::VOLUMEN,$volumen);
	  		$parametros .= "&volumen=".$volumen;		
		  }
    	 /*******************************************************************************************************/   	 		    		  	
		  
  	/**************************************************************************************************************/
	if($this->getRequestParameter('idioma_id')){
      $c->add(DocumentacionPeer::IDIOMA_ID,$this->getRequestParameter('idioma_id'));
	  $parametros .= "&idioma_id=".$this->getRequestParameter('idioma_id');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('titulo')){
      $c->add(DocumentacionPeer::TITULO,'%'.$this->getRequestParameter('titulo').'%',Criteria::LIKE);
	  $parametros .= "&titulo=".$this->getRequestParameter('titulo');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('codigoBarras')){
      $c->add(DocumentacionPeer::CODIGO_BARRAS,'%'.$this->getRequestParameter('codigoBarras').'%',Criteria::LIKE);
	  $parametros .= "&codigoBarras=".$this->getRequestParameter('codigoBarras');		
	}
    /**************************************************************************************************************/
    if($this->getRequestParameter('ubicacion')){
      $c->add(DocumentacionPeer::UBICACION,'%'.$this->getRequestParameter('ubicacion').'%',Criteria::LIKE);
	  $parametros .= "&ubicacion=".$this->getRequestParameter('ubicacion');		
	}
    /**************************************************************************************************************/            
    
    $c->add(DocumentacionPeer::ESTADODOCUMENTACION_ID,1);
	$c->add(DocumentacionPeer::TIPODOCUMENTACION_ID,$tipo_documentacion);
	$c->addDescendingOrderByColumn(DocumentacionPeer::DOCUMENTACION_ID);  	  	  	
  	/*************************************************************************************************************/
	//$pager = new sfPropelPager('MediosMagneticos', 10);	
	//$pager->setCriteria($c);        
	//$pager->setPage($this->getRequestParameter('page', 1));
	//$pager->init();
	//$this->pager = $pager;
	
	$pager = MediosMagneticosPeer::doSelect($c);
	$this->parametros = $parametros;
	$this->tipo_documentacion =$tipo_documentacion;
	$this->username = $this->getUser()->getAttribute('username', '', 'subscriber');				    
	/**************************************************************************************************************/
	$userInventariador = array();
	$userCreador = array();
	
	foreach($pager as $medios_magneticos){
		/***************************************Consulta para el inventariador**********************************/    
	    $c = new Criteria();
		$c->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$medios_magneticos->getDocumentacionId());
		$c->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,2);	
		$userInv = UdUsuarioDocumentacionPeer::doSelectOne($c);
		$userInventariador[] = $userInv->getUsuario();	
		/*******************************************************************************************************/
		
		/***************************************Consulta para el Creador****************************************/    
	    $b = new Criteria();
		$b->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$medios_magneticos->getDocumentacionId());
		$b->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,1);	
		$userCre = UdUsuarioDocumentacionPeer::doSelectOne($b);	
		$userCreador[] = $userCre->getUsuario();
		/*******************************************************************************************************/
	}
	$this->usuarioInv = $userInventariador;
	$this->usuarioCre = $userCreador;	
	$this->pager = $pager;
	
  }
  
  public function executeDelete()
  {
    $medios_magneticos = MediosMagneticosPeer::retrieveByPk($this->getRequestParameter('mediosmagneticos_id'));

    $this->forward404Unless($medios_magneticos);

    $medios_magneticos->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/medios_magneticos/list');
  }
